import{_ as s,a0 as r,w as l,s as x,I as i,x as t,a1 as o,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"从 XP 迁移到 Linux 的入门指南 | LCTT x X-CMD","titleTemplate":false,"description":"从 XP 迁移到 Linux 的入门指南 | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"从 XP 迁移到 Linux 的入门指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"从 XP 迁移到 Linux 的入门指南 | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/A Beginners Guide for XP Users to Switch to Linux","title":"从 XP 迁移到 Linux 的入门指南","tag":"201404","desc":""},"relativePath":"201404/A Beginners Guide for XP Users to Switch to Linux.md","filePath":"[post].md"}'),L={name:"201404/A Beginners Guide for XP Users to Switch to Linux.md"};function p(d,n,f,w,m,a){const u=r("Link");return l(),x("div",null,[n[17]||(n[17]=i("h1",{id:"从-xp-迁移到-linux-的入门指南",tabindex:"-1"},[t("从 XP 迁移到 Linux 的入门指南 "),i("a",{class:"header-anchor",href:"#从-xp-迁移到-linux-的入门指南","aria-label":"Permalink to “从 XP 迁移到 Linux 的入门指南”"},"​")],-1)),n[18]||(n[18]=i("p",null,[i("img",{src:"http://www.linuxfederation.com/wp-content/uploads/2014/04/Switch_To_linux.jpeg",alt:""})],-1)),n[19]||(n[19]=i("p",null,"Microsoft 已经不再支持 Windows XP 了。大多数人也许并不关心这事儿，但对于知道使用服务终止的软件会有麻烦的你来说，做点儿改变的时候到了。你可以安装同样落伍的 Windows 7，或者安装没人喜欢的 Windows 8。或者，你可以从风格众多的 Linux 中选择一款来安装，化身成为 Linux 用户这个精英团体的一员。",-1)),n[20]||(n[20]=i("p",null,"和 Windows 可不一样，你不需要为了让系统启动运行而支付数百美元。Linux 是免费的，并且未来也不会收费。Linux 附带一切必要的应用程序，比如互联网浏览器、电子邮件客户端、视频播放器、照片编辑器等一大堆同样免费的软件，但要想享用这些软件，你首先得说服自己迁移到 Linux。你可能会想，我本来可以好好儿地继续用我旧版的 Windows，干嘛要费神用别的东西。听我解释，这花不了多长时间。",-1)),n[21]||(n[21]=i("p",null,"Linux 和 Windows 不一样，它可不是 Microsoft 花钱雇人做的，而是在像 Red Hat、IBM、HP、Samsung 等众多 Linux 基金会领导下的技术巨头以及全世界成千上万的志愿者的协作下开发的。所以，你可以确信你在用的不是个别大牛工程师的小众作品，而是开发人员遍布全球的坚实的操作系统。",-1)),i("p",null,[n[1]||(n[1]=t("这一点使得 Linux 跻身全世界最安全的操作系统之列。好吧，百分之百的安全是不存在的，但使用 Linux 能保证安全在你身边寸步不离，这是 Google、Facebook、Twitter、IBM、NASA 等公司使用 Linux 的唯一理由。这里列出了",-1)),o(u,{href:"http://www.linuxfederation.com/linux-everywhere/"},{default:e(()=>[...n[0]||(n[0]=[t("使用 Linux 的世界顶级公司和组织",-1)])]),_:1}),n[2]||(n[2]=t("。Linux 是个非常轻量级的操作系统，却既能支持最前沿的新硬件，也能支持几十年前的老硬件。",-1))]),n[22]||(n[22]=i("p",null,"现在，如果关于 Linux 的概念已经勾起了你的兴致，我们来看看房间里的下一头大象（译注：原文是 the next elephant in the room。the elephant in the room 通常指显而易见却避而不谈的问题）—— 你在 Windows XP 下最爱的应用程序。Linux 环境有你在 Windows 下爱用的绝大部分应用程序，包括 Firefox、Chrome、Steam、VLC、Skype 和 Team Viewer。如果你找不到你某个你在 Windows 上用过的软件，那么试试 Linux 环境下数量庞大的替代品吧。与你的 Windows 应用程序相比，它们的功能更强大，而且都是协作开发的。",-1)),n[23]||(n[23]=i("p",null,"列举几个常见的替代方案：Libre Office 可以代替 Microsoft Office，Thunderbird 可以替代 Outlook，Gimp 可以替代 Adobe Photoshop，它们全都永久免费，而且你不用为每年的小更新升级支付数百美元。你不会像用 Windows 那样只有很少的几种应用程序可供选择（这是 Microsoft 的垄断行为造成的），也就是说，任何时候如果你对 Libre Office 不满意，你都可以改用另一个非常可靠的办公软件套件 Open Office。",-1)),n[24]||(n[24]=i("p",null,"使用 Linux 最好的事情是，你根本不用担心病毒，也完全没必要安装昂贵且耗费资源严重的网络安全程序，因为它们几乎保护不了你。Windows 立足于让整个网络安全事业有利润可榨取，这么看来，反病毒公司真是干得不错。相反，Linux 并不鼓励这种行为，它本就是全世界最安全的操作系统之一。这也解释了为什么大部分全球防务系统和股票交易系统运行的是 Linux。",-1)),n[25]||(n[25]=i("p",null,"好吧，如果你因为从没见过有人用 Linux 所以还是不服的话，看看你和你身边人的安卓手机吧，它就是在 Linux 上构建的。电视、空调、洗衣机和你钟爱的咖啡机运行的也是 Linux。你已经生活在了一个运行 Linux 的世界里，但你却拒绝成为这个世界的一部分。再前进一小步吧，你马上就会变成 Linux 精英用户了。",-1)),n[26]||(n[26]=i("p",null,"别说教了，咱们开始用用 Linux 吧。首先我们要选择一款 Linux，这是最有意思的部分了。初次选择 Linux 就像哈利·波特选择魔杖一样。每个风格不同的 Linux 都运行在相同的我们称之为“内核（Kernel）”的坚实基础之上，不同风格的 Linux 我们称之为“发行版”。",-1)),i("p",null,[n[4]||(n[4]=t("Linux 目前有数百个发行版，",-1)),o(u,{href:"http://distrowatch.com/"},{default:e(()=>[...n[3]||(n[3]=[t("Distrowatch",-1)])]),_:1}),n[5]||(n[5]=t(" 按流行度顺序列出了所有发行版。Ubuntu、Linux Mint、Fedora、Debian 以及 Open Suse 是几个比较著名的 Linux 发行版。如果你怀念 Windows XP 的感觉，那最好选择 Linux Mint。如果你想体验一下新奇的东西，尝试一下 Ubuntu 的 Unity 界面、Fedora 的 Gnome 界面或者 Open Suse 的 KDE 界面。Unity、Gnome、KDE 是不同的用户界面的名字，我们称之为“桌面环境（Desktop Environment）”。这些桌面环境在很老的系统上也能使用，但如果你真的要在很古老的机器上使用 Linux，你可以试试轻量级的桌面环境，比如 XFCE 和 LXDE，它们很轻量级，用户界面要简单一些。",-1))]),n[27]||(n[27]=i("p",null,"好了，选择一款你喜欢的 Linux 发行版并开始使用吧。Linux 是免费、稳定并且安全的，如果还有什么说的，那就是，如果你用着开心，就为 Linux 基金会那些家伙的出色工作捐点钱吧。我不打算写安装教程，因为那些东西网上到处都是。我在线上和线下帮助我的朋友迁移到 Linux，你也应该帮助你的朋友迁移到 Linux。",-1)),n[28]||(n[28]=i("hr",null,null,-1)),i("p",null,[n[7]||(n[7]=t("译自: ",-1)),o(u,{href:"http://www.linuxfederation.com/beginners-guide-xp-users-switch-linux/"},{default:e(()=>[...n[6]||(n[6]=[t("http://www.linuxfederation.com/beginners-guide-xp-users-switch-linux/",-1)])]),_:1})]),i("p",null,[n[10]||(n[10]=t("译者：",-1)),o(u,{href:"https://github.com/blueabysm"},{default:e(()=>[...n[8]||(n[8]=[t("sailing",-1)])]),_:1}),n[11]||(n[11]=t(" 校对：",-1)),o(u,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:e(()=>[...n[9]||(n[9]=[t("wxy",-1)])]),_:1})]),i("p",null,[n[14]||(n[14]=t("本文由 ",-1)),o(u,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[12]||(n[12]=[t("LCTT",-1)])]),_:1}),n[15]||(n[15]=t(" 原创翻译，",-1)),o(u,{href:"http://linux.cn/"},{default:e(()=>[...n[13]||(n[13]=[t("Linux中国",-1)])]),_:1}),n[16]||(n[16]=t(" 荣誉推出",-1))])])}const X=s(L,[["render",p]]);export{P as __pageData,X as default};
